final class Document implements AutoCloseable {           // the Whole
    private static final Cleaner CLEANER = Cleaner.create();
    private final List<Paragraph> parts = new ArrayList<>();
    private final Cleaner.Cleanable cleanable;

    Document(Backing backing) {
        this.cleanable = CLEANER.register(this, new Backing.State(backing)); // no `this` capture
    }
    Paragraph addParagraph(String text) { var p = new Paragraph(text); parts.add(p); return p; }
    @Override public void close() { parts.forEach(Paragraph::close); cleanable.clean(); }
}
